//  UTILITÁRIOS
// ═══════════════════════════════════════════════════════════════

/**
 * Sorteia N perguntas do banco, garantindo variedade de categorias.
 * @param {number} n - Número de perguntas desejadas (padrão: 20)
 * @param {string[]} categories - Categorias para incluir (vazio = todas)
 * @returns {Array} Perguntas sorteadas e embaralhadas
 */
function pickQuestions(n = 20, categories = []) {
  let pool = [...ALL_QUESTIONS];

  // Filtrar por categorias, se especificadas
  if (categories.length > 0) {
    pool = pool.filter(q => categories.includes(q.category));
  }

  // Agrupar por categoria
  const byCategory = {};
  pool.forEach(q => {
    if (!byCategory[q.category]) byCategory[q.category] = [];
    byCategory[q.category].push(q);
  });

  // Embaralhar cada categoria
  Object.values(byCategory).forEach(arr => shuffleArray(arr));

  // Distribuir proporcionalmente
  const catNames = Object.keys(byCategory);
  const perCat = Math.floor(n / catNames.length);
  const remainder = n % catNames.length;

  let selected = [];
  catNames.forEach((cat, i) => {
    const take = perCat + (i < remainder ? 1 : 0);
    selected.push(...byCategory[cat].slice(0, take));
  });

  // Se não alcançou N (categorias com poucas perguntas), completar
  if (selected.length < n) {
    const selectedSet = new Set(selected);
    const remaining = pool.filter(q => !selectedSet.has(q));
    shuffleArray(remaining);
    selected.push(...remaining.slice(0, n - selected.length));
  }

  // Embaralhar resultado final
  shuffleArray(selected);
  return selected.slice(0, n);
}

function shuffleArray(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// Estatísticas do banco
function getStats() {
  const stats = {};
  ALL_QUESTIONS.forEach(q => {
    stats[q.category] = (stats[q.category] || 0) + 1;
  });
  return stats;
}
